package at.hausgarten.service;

import org.json.*;
import java.time.*;
import java.util.*;

/** Acceptance/decline and conversion checks share the existing owner request transaction. */
final class OfferDecisionService {
    private final OwnerRepository repository;private final Clock clock;
    OfferDecisionService(OwnerRepository repository){this(repository,Clock.systemUTC());}
    OfferDecisionService(OwnerRepository repository,Clock clock){this.repository=repository;this.clock=clock;}
    private JSONObject current(String id)throws Exception {String raw=repository.ownerValue(OfferDecisionRules.PREFIX+"current:"+id,"");if(raw.isEmpty())return null;JSONObject value=new JSONObject(raw);OfferDecisionRules.version(value);return value;}
    JSONObject query(String name,JSONObject args)throws Exception {
        if(!name.equals("get_offer_decision_history"))throw new IllegalArgumentException("Unbekannte Angebotsentscheidung.");String id=args.getString("offer_id");JSONObject offer=PixelMcpWriteTools.find(repository.effective().getJSONArray("offers"),id);JSONArray rows=new JSONArray(repository.ownerValue(OfferDecisionRules.PREFIX+"history:"+id,"[]")),items=new JSONArray();int offset=RevierRules.integer(args,"offset",0,1000000,0),limit=RevierRules.integer(args,"limit",1,100,50);for(int i=rows.length()-1-offset;i>=0&&items.length()<limit;i--)items.put(OfferDecisionRules.publicDecision(rows.getJSONObject(i)));JSONObject decision=current(id);JSONObject result=new JSONObject().put("formatVersion",1).put("offer_id",id).put("history",items).put("items",items).put("total",rows.length()).put("record_hash",PixelMcpWriteTools.hash(DriveJournalRules.clean(offer))).put("document_status",offer.optString("status"));
        if(decision!=null){JSONObject map=new JSONObject().put(id,decision),shown=OfferDecisionRules.matching(offer,map);result.put("decision",shown).put("decision_status",shown.getString("decision"));}else result.put("decision_status","not_recorded");String revision=repository.ownerValue(OfferDecisionRules.PREFIX+"revision:"+id,"");if(!revision.isEmpty())result.put("revision",new JSONObject(revision));return result;
    }
    JSONObject perform(String name,JSONObject args,String request)throws Exception {
        if(!Arrays.asList("record_offer_acceptance","decline_offer").contains(name))throw new IllegalArgumentException("Unbekannte Angebotsentscheidung.");String requestId=RevierRules.text(args,"request_id",128,true);if(requestId.length()<8)throw new PixelMcpWriteTools.Rejected("INVALID_INPUT","Stabile Anfragekennung erforderlich.");String fingerprint=PixelMcpWriteTools.hash(new JSONObject().put("operation",name).put("args",args)),receipt=OfferDecisionRules.PREFIX+"request:"+PixelMcpWriteTools.hash(requestId);String previous=repository.ownerValue(receipt,"");if(!previous.isEmpty()){JSONObject saved=new JSONObject(previous);if(!fingerprint.equals(saved.getString("fingerprint")))throw new PixelMcpWriteTools.Rejected("REPLAY_MISMATCH","Diese Anfragekennung gehört zu anderen Entscheidungsangaben.");return new JSONObject(saved.getJSONObject("result").toString()).put("replayed",true);}
        String id=RevierRules.id(args,"offer_id",true);JSONObject offer=PixelMcpWriteTools.find(repository.effective().getJSONArray("offers"),id);if(!PixelMcpWriteTools.hash(DriveJournalRules.clean(offer)).equals(args.getString("expected_record_hash")))throw new PixelMcpWriteTools.Rejected("WRITE_CONFLICT","Angebot wurde geändert. Entscheiden Sie anhand der aktuellen finalisierten Version.");OfferDecisionRules.requireFinal(offer);repository.readDocument(offer);JSONObject existing=current(id);String version=OfferDecisionRules.contentVersion(offer);
        if(existing!=null)throw new PixelMcpWriteTools.Rejected(existing.getString("content_version").equals(version)?"OFFER_DECISION_ALREADY_RECORDED":"OFFER_FINAL_VERSION_CHANGED","Diese Angebotsversion hat bereits eine Entscheidung oder einen widersprüchlichen Dokumentstand. Für Änderungen eine neue Version anlegen; alte Entscheidung bleibt erhalten.");
        boolean acceptance=name.equals("record_offer_acceptance");if(!acceptance&&offer.optString("status").equals("accepted"))throw new PixelMcpWriteTools.Rejected("OFFER_ALREADY_CONVERTED","Angenommenen Auftrag nicht durch eine Ablehnungsmarkierung aufheben. Bestehenden Vorgang gesondert klären.");String stamp=clock.instant().toString();JSONObject decision=new JSONObject().put("formatVersion",1).put("decision_id",RevierRules.newId("offer_decision",requestId)).put("offer_id",id).put("content_version",version).put("decision",acceptance?"accepted":"declined").put("recorded_at",stamp).put("pdf_sha256",offer.getString("pdf_sha256")).put("request_id",requestId);
        if(acceptance){String at=RevierRules.instant(RevierRules.text(args,"accepted_at",80,true)),evidence=RevierRules.text(args,"evidence",10000,true);if(Instant.parse(at).isAfter(clock.instant().plusSeconds(120)))throw new PixelMcpWriteTools.Rejected("ACCEPTANCE_TIME_REVIEW_REQUIRED","Annahmezeit liegt in der Zukunft. Zeitpunkt und Geräteuhr prüfen.");decision.put("accepted_at",at).put("evidence",evidence);}else decision.put("reason",RevierRules.text(args,"reason",10000,false));RevierRules.bounded(decision);
        JSONArray history=new JSONArray(repository.ownerValue(OfferDecisionRules.PREFIX+"history:"+id,"[]"));history.put(decision);repository.putOwnerValue(OfferDecisionRules.PREFIX+"history:"+id,history.toString());repository.putOwnerValue(OfferDecisionRules.PREFIX+"current:"+id,decision.toString());JSONObject result=new JSONObject().put("offer_id",id).put("decision",OfferDecisionRules.publicDecision(decision)).put("local_state","local_saved").put("cloud_confirmed",false).put("invoice_created",false).put("replayed",false);repository.putOwnerValue(receipt,new JSONObject().put("fingerprint",fingerprint).put("result",result).toString());return result;
    }
    void requireConversionDecision(JSONObject offer)throws Exception {
        JSONObject decision=current(offer.getString("id"));if(decision!=null){if(!decision.getString("content_version").equals(OfferDecisionRules.contentVersion(offer)))throw new PixelMcpWriteTools.Rejected("OFFER_FINAL_VERSION_CHANGED","Annahmenachweis gehört zu einer anderen Dokumentversion. Auftrag nicht angelegt.");if(!decision.getString("decision").equals("accepted"))throw new PixelMcpWriteTools.Rejected("OFFER_DECLINED","Abgelehntes Angebot erzeugt keinen Auftrag. Neue Angebotsversion bei Überarbeitung anlegen.");}
        if(OfferDecisionRules.local(repository.state())&&decision==null)throw new PixelMcpWriteTools.Rejected("OFFER_ACCEPTANCE_EVIDENCE_REQUIRED","Annahmezeit und nachvollziehbaren Nachweis für genau diese Version erfassen, bevor ein Auftrag angelegt wird.");
    }
    void linkRevision(String sourceId,String targetId,String request)throws Exception {JSONObject source=PixelMcpWriteTools.find(repository.effective().getJSONArray("offers"),sourceId);JSONObject revision=new JSONObject().put("formatVersion",1).put("offer_id",targetId).put("parent_offer_id",sourceId).put("parent_content_version",OfferDecisionRules.contentVersion(source)).put("created_at",clock.instant().toString()).put("request_id",request);repository.putOwnerValue(OfferDecisionRules.PREFIX+"revision:"+targetId,revision.toString());}
}
